def transform(g):
    h,w=len(g),len(g[0])
    # find connected shapes (4-conn, nonzero)
    seen=set(); shapes=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and (i,j) not in seen:
                col=g[i][j]; stack=[(i,j)]; seen.add((i,j)); cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and g[ny][nx]==col:
                            seen.add((ny,nx)); stack.append((ny,nx))
                rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
                r0,c0=min(rs),min(cs)
                block=[[col if (r0+a,c0+b) in set(cells) else 0 for b in range(max(cs)-c0+1)] for a in range(max(rs)-r0+1)]
                shapes.append((r0,c0,block))
    shapes.sort(key=lambda s:(s[1],s[0]))  # left-to-right
    out=[[0]*w for _ in range(h)]
    top=0
    for k,(r0,c0,block) in enumerate(shapes):
        r=top; c=k
        for a,row in enumerate(block):
            for b,v in enumerate(row):
                if v: out[r+a][c+b]=v
        top=r+len(block)-1  # overlap: next top = this bottom row
    return out
